import { DataStateHandler } from 'components';
import type { BrandAvatarItemProps } from 'components/BrandAvatar/Components/BrandAvatarItem/interface';

import type { BeerEvolutionBreakdownData } from '../../../../types';
import { resolveBeerEvolutionTestId } from './beerEvolutionBreakdownSection.utils';
import { BeerEvolutionReadyContent } from './BeerEvolutionReadyContent';

const SKELETON_PROPS = {
  height: '280px',
  width: '100%',
  length: 1,
  borderRadius: 'none' as const,
};

interface BeerEvolutionChartContentProps {
  data: BeerEvolutionBreakdownData | null | undefined;
  loading: boolean;
  error: boolean;
  isEmpty: boolean;
  stateMessage?: { title: string; description: string };
  dataTestId?: string;
  chartValues: number[];
  chartLabelsLength: number;
  waterfallLabels: string[];
  brandAvatarData: BrandAvatarItemProps[];
}

export const BeerEvolutionChartContent = ({
  data,
  loading,
  error,
  isEmpty,
  stateMessage,
  dataTestId,
  chartValues,
  chartLabelsLength,
  waterfallLabels,
  brandAvatarData,
}: BeerEvolutionChartContentProps) => {
  const showReadyContent = Boolean(data) && !isEmpty;

  return (
    <DataStateHandler
      loading={loading}
      error={error}
      empty={isEmpty}
      message={stateMessage}
      skeletonProps={SKELETON_PROPS}
      dataTestId={resolveBeerEvolutionTestId(
        dataTestId,
        'state',
        'beer-evolution-breakdown-state',
      )}
    >
      {showReadyContent ? (
        <BeerEvolutionReadyContent
          data={data!}
          dataTestId={dataTestId}
          chartValues={chartValues}
          chartLabelsLength={chartLabelsLength}
          waterfallLabels={waterfallLabels}
          brandAvatarData={brandAvatarData}
        />
      ) : null}
    </DataStateHandler>
  );
};
